INSERT INTO procedure_log_mst (
	     log_id
	   , apply_date
	   , procedure_id
	   , job_type
	   , company_code
	   , input_parameter
	   , start_date
	   , status
	)
	VALUES (
	     #{logId}
	   , #{applyDate}
	   , #{procedureId}
	   , #{jobType}
	   , #{companyCode}
	   , #{inputParameter}
	   , NOW()
	   , #{status}
	)

