INSERT INTO procedure_log_dtl (
	     log_id
	   , seq
	   , log_datetime
	   , log_contents
	)
	VALUES (
	     #{logId}
	   , (SELECT COALESCE(MAX(seq), 0) + 1 FROM procedure_log_dtl WHERE log_id = #{logId})
	   , NOW()
	   , #{logContents}
	)
